<script>
(() => {
 const form=document.getElementById('academic-access-form'),target=document.getElementById('academic-results'),select=form.elements.department_id,url=<?php echo json_encode(route('academic.directory'), 15, 512) ?>;let sequence=0;
 const choose=async id=>{try{const response=await fetch(url+'?university_id='+id,{headers:{Accept:'application/json'}});if(!response.ok)throw Error();const data=await response.json();form.elements.university_id.value=id;document.getElementById('academic-selected').textContent=data.institution.name;select.replaceChildren(new Option('Institution-wide access',''));for(const faculty of data.faculties)for(const department of faculty.departments)select.add(new Option(`${faculty.name} · ${department.name} · ${String(department.adoption_status).replaceAll('_',' ')}`,department.id));select.value=<?php echo json_encode((string)old('department_id', ''), 512) ?>;target.replaceChildren();}catch{target.textContent='Organisation details could not be loaded. Please try again.';}};
 const search=async()=>{const q=document.getElementById('academic-search').value.trim();if(q.length<2){target.textContent='Type at least two characters.';return;}const current=++sequence;target.textContent='Searching…';try{const response=await fetch(url+'?q='+encodeURIComponent(q),{headers:{Accept:'application/json'}});if(!response.ok)throw Error();const data=await response.json();if(current!==sequence)return;target.replaceChildren();for(const item of data.institutions){const button=document.createElement('button');button.type='button';button.className='block w-full rounded-xl border p-3 text-left';button.textContent=`${item.name} · ${String(item.adoption_status).replaceAll('_',' ')}`;button.addEventListener('click',()=>choose(item.id));target.append(button);}if(!data.institutions.length)target.textContent='No match found. You can request a directory addition through departmental onboarding.';}catch{target.textContent='Search could not be completed. Please try again.';}};
 document.getElementById('academic-search-button').addEventListener('click',search);document.getElementById('academic-search').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();search();}});form.addEventListener('submit',e=>{if(!form.elements.university_id.value){e.preventDefault();target.textContent='Choose an institution from the search results first.';}});if(form.elements.university_id.value)choose(form.elements.university_id.value);
})();
</script>
